const path = require("path");
const { Client } = require("pg");
const dotenv = require("dotenv");

dotenv.config({ path: path.join(__dirname, "..", ".env"), quiet: true });

// Wave 5 C2 (decision V7): applies article revisions whose scheduled time has passed. Run every five
// minutes by deploy/vps/scripts/publish-scheduled-articles.sh. It uses the app's own apply logic
// (compiled into scripts/generated by export-catalog), in one transaction under the article lock,
// so a scheduled publish is exactly a manual apply by the administrator who scheduled it.
async function main() {
  const { publishDueRevisions } = require("./generated/article-revisions");
  const client = new Client({ connectionString: process.env.UNNATIVIDYA_DATABASE_URL || "postgresql://unnatividya_app:unnatividya_app@localhost:5432/unnatividya" });
  await client.connect();
  try {
    await client.query("begin");
    const { applied, failed } = await publishDueRevisions(client);
    await client.query("commit");
    const stamp = new Date().toISOString();
    if (applied.length || failed.length) console.log(`${stamp} published ${applied.length} scheduled revision(s)${applied.length ? `: ${applied.join(", ")}` : ""}; refused ${failed.length}${failed.length ? `: ${failed.map(item => `${item.id} (${item.error})`).join("; ")}` : ""}.`);
  } catch (error) {
    await client.query("rollback").catch(() => {});
    throw error;
  } finally {
    await client.end();
  }
}

main().catch((error) => {
  console.error(`${new Date().toISOString()} scheduled publishing failed: ${error instanceof Error ? error.message : error}`);
  process.exitCode = 1;
});
